//! The eight Duckpools lending pools on mainnet, as deployed.
//!
//! Identities come from `duckpools/off-chain-bot/consts.py` (CC0) and the
//! pool scripts from the unspent pool boxes captured on 2026-09-05, which
//! are the fixtures under `test/fixtures`. A pool NFT was minted with more
//! than one unit (the deployer's token bag holds the rest), so the script
//! is what identifies the pool box, and the NFT confirms it.

/// One lending pool.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Pool {
    /// Short stable key: `erg`, `sigusd`, …
    pub key: &'static str,
    /// The pooled asset's ticker as users know it.
    pub ticker: &'static str,
    /// Decimals of the pooled asset (and of its lend token).
    pub decimals: u8,
    pub pool_nft: &'static str,
    pub lend_token: &'static str,
    pub borrow_token: &'static str,
    /// The pooled token's id; `None` for the ERG pool, whose asset is the
    /// box value itself.
    pub currency_id: Option<&'static str>,
    /// The pool contract, hex.
    pub ergo_tree: &'static str,
    /// Where a lend order is posted for the bots.
    pub lend_proxy_address: &'static str,
    /// Where a withdraw order is posted.
    pub withdraw_proxy_address: &'static str,
    /// The two service-fee steps, in asset units: `1/160` up to the first,
    /// `1/200` up to the second, `1/250` above.
    pub fee_thresholds: (i64, i64),
    /// The interest parameter box (rate coefficients), the head child
    /// interest box (rate history) and its parent.
    pub interest_param_nft: &'static str,
    pub child_nft: &'static str,
    pub parent_nft: &'static str,
    /// The pool parameter box: liquidation thresholds and penalties per
    /// collateral, the collateral price sources, the service fee script.
    pub param_nft: &'static str,
    /// The collateral contract every loan of this pool sits under.
    pub collateral_address: &'static str,
    pub borrow_proxy_address: &'static str,
    pub repay_proxy_address: &'static str,
    pub partial_repay_proxy_address: &'static str,
    /// The Spectrum pool that prices ERG in this pool's asset, for ERG
    /// collateral; `None` where the pool takes no ERG collateral (the ERG
    /// pool lends ERG against tokens).
    pub erg_dex_nft: Option<&'static str>,
    /// The tokens this pool takes as collateral, each with the Spectrum
    /// pool that prices it in ERG. Only the ERG pool has any.
    pub token_collaterals: &'static [CollateralAsset],
}

/// A token the ERG pool lends against.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub struct CollateralAsset {
    pub id: &'static str,
    pub ticker: &'static str,
    pub decimals: u8,
    pub dex_nft: &'static str,
}

