/// The pool with this key, if any.
pub fn pool_by_key(key: &str) -> Option<&'static Pool> {
    POOLS.iter().find(|p| p.key == key)
}

/// The pool with this NFT, if any.
pub fn pool_by_nft(nft: &str) -> Option<&'static Pool> {
    POOLS.iter().find(|p| p.pool_nft.eq_ignore_ascii_case(nft))
}

/// The pool whose lend token this is, if any.
pub fn pool_by_lend_token(id: &str) -> Option<&'static Pool> {
    POOLS.iter().find(|p| p.lend_token.eq_ignore_ascii_case(id))
}
